// @vitest-environment jsdom
// Independent diagnosis only: current typed save + valid PNG; external store read rejects.
import { buildWorld } from '@type-pal/content'
import { afterEach, expect, test, vi } from 'vitest'
import { chromePng, installShellHost, type ShellHost } from './__tests__/runtime-shell/dom-host.js'
import { drain, key } from './__tests__/runtime-shell/driver.js'
import { shellProject } from './__tests__/runtime-shell/project.js'
import type { OpeningMenuObservation } from './opening-menu.js'
import { buildCurrentSavePayload } from './save/ops.js'
import { MemorySaveStore } from './save/store.js'
import type { SaveMeta } from './save/types.js'

let host: ShellHost | undefined
afterEach(() => host?.close())

test('Codex D-Q01-1: legal current slot + thumbnail storage IO rejection escapes menu promise', async () => {
  host = await installShellHost()
  const { project } = await shellProject()
  const { loadMenuAssets } = await import('./menu/menu-box.js')
  const { loadGlyphs } = await import('./text/glyph.js')
  const { projectItemsView } = await import('./runtime-project-view.js')
  const { runOpeningMenu } = await import('./opening-menu.js')
  const entry = project.manifest.entryPoints[0]!
  const store = new MemorySaveStore({ kind: 'project', projectId: 'shell-project' })
  const meta: SaveMeta = {
    slotId: 'm01', kind: 'manual', party: [{ name: 'Hero', level: 1 }],
    mapName: 'a', savedAt: 1,
  }
  const payload = buildCurrentSavePayload(
    buildWorld(entry.startWorld, project.actorsById),
    { sceneId: 'a', pos: { col: 2, row: 2, height: 0 }, facing: 'down' },
    'shell-project',
  )
  const thumb = new Blob([chromePng().slice().buffer], { type: 'image/png' })
  await store.putSlot(meta, payload, thumb)
  expect(await store.getThumb('m01')).toBe(thumb)
  const read = vi.spyOn(store, 'getThumb').mockRejectedValue(
    new DOMException('Codex thumbnail storage read failed', 'UnknownError'),
  )
  const canvas = document.querySelector('canvas')!
  const snapshots: OpeningMenuObservation[] = []
  const done = runOpeningMenu({
    ctx: canvas.getContext('2d')!, glyphs: await loadGlyphs(),
    bg: await createImageBitmap(thumb),
    items: [{ id: 'first', label: 'A' }], worldScale: 4, locale: {},
    menuAssets: await loadMenuAssets(projectItemsView(project.items), project.imageCache),
    saveStore: store, observe: s => snapshots.push(s),
  })
  host.frame()
  await key(host, 'ArrowUp')
  await key(host, 'Enter')
  await drain()
  host.frame()
  expect(read).toHaveBeenCalledWith('m01')
  expect(snapshots.at(-1)?.phase).toBe('menu')
  // Clean up through another legal menu action; the detached enterLoad rejection still escapes.
  await key(host, 'ArrowDown')
  await key(host, 'Enter')
  await expect(done).resolves.toEqual({ kind: 'new', entryId: 'first' })
})
